CREATE OR REPLACE FUNCTION public.get_contact_effectiveness(p_contact_id uuid, p_days integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$ DECLARE result jsonb; total_interactions int; total_deals int; won_deals int; BEGIN total_interactions := (SELECT count(*) FROM interactions WHERE contact_id = p_contact_id AND data_interacao >= now() - (p_days || ' days')::interval); total_deals := (SELECT count(*) FROM interactions WHERE contact_id = p_contact_id AND type IN ('deal','sale') AND data_interacao >= now() - (p_days || ' days')::interval); won_deals := (SELECT count(*) FROM interactions WHERE contact_id = p_contact_id AND status = 'won'); SELECT jsonb_build_object( 'overall_score', LEAST(100, total_interactions * 5), 'conversion_rate', CASE WHEN total_interactions > 0 THEN ROUND((won_deals::numeric / total_interactions) * 100, 2) ELSE 0 END, 'avg_deal_size', 0, 'avg_sales_cycle_days', NULL, 'response_rate', CASE WHEN total_interactions > 0 THEN 75.0 ELSE 0 END, 'meeting_to_deal_ratio', CASE WHEN total_interactions > 0 THEN ROUND((total_deals::numeric / total_interactions) * 100, 2) ELSE 0 END, 'best_channel', 'email', 'best_time_slot', 'morning', 'total_interactions', total_interactions, 'total_deals', total_deals, 'won_deals', won_deals, 'total_value', 0, 'recommendations', ARRAY['Mantenha contato regular','Personalize comunica��es']::text[] ) INTO result; RETURN result; END; $function$
